head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:400px;height:250px;background-color:var(--ws-gray-300);"
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // getPosition() 은 부모 기준 위치를 반환하므로 위치잡을 부모(parent1) 컨테이너를 먼저 생성한다.
    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // iframe 은 dynamicCreate 시 inline src 를 주면 _dynamicCreateAfter 가
    // 미로딩 contentDocument.documentElement(null) 접근으로 오류 → src 없이 생성 후 setSrc.
    // id 는 non-empty("target1") 로 지정(빈 cID 는 iframe 초기 contentDocument race 로 TypeError).
    strTarget += '<w2:iframe ' + strNameSpace + ' ' + cList + ' id="target1"></w2:iframe>';

    // target 생성 (parent1 을 부모로)
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "iframe",
        strTarget,
        parent1
    );

    // 생성 후 setSrc 로 내용 로드(inline src 금지 규칙 → 생성 후 setSrc).
    scwin.target1.setSrc("/sample/common_link/iframe_link_1.xml");
}
